module pulse_detect #(
    parameter s0 = 2'b00,
    parameter s1 = 2'b01,
    parameter s2 = 2'b10,
    parameter s3 = 2'b11
) (
    input clk,
    input rst_n,
    input data_in,
    output reg data_out
);

reg [1:0] state;
localparam IDLE = 2'b00, PULSE_1 = 2'b01, PULSE_2 = 2'b10;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= IDLE;
        data_out <= 1'b0;
    end else begin
        case (state)
            IDLE: begin
                if (data_in == 1'b1)
                    state <= PULSE_1;
                    data_out <= 1'b0;
            end
            PULSE_1: begin
                if (data_in == 1'b0) state <= PULSE_2; else state <= IDLE;
            end
            PULSE_2: begin
                if (data_in == 1'b1)
                    state <= PULSE_1;
                    data_out <= 1'b1;
            end
        endcase
    end
end

endmodule
